  "claim": {
    "component_id": "C012.component",
    "value": "A delegation form may establish authority without documenting approval of a particular order.",
    "scope": "The possible evidentiary contribution of a delegation form; authority and order-specific approval are distinct.",
    "provenance": {
      "refs": [
        {
          "source_id": "P010",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span directly supports the distinction, including its modal qualification."
    }
  },
  "signal_basis": {
    "component_id": "C012.signal_basis",
    "value": "Examine approval content and applicable authority separately, checking whether approval records link to the particular order and establish approval before placement.",
    "scope": "Documentary evidence examined for authority, order-specific approval and timing.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P015",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans specify separate recording of approval content and authority, together with checks of order linkage and timing."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C012.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The bounded claim is supported without an unresolved empirical bridging relation."
    }
  },
  "rationale": "A document granting authority can establish permission to approve orders without recording that this authority was exercised for a particular order. The operation distinguishes these evidentiary questions, licensing the claim's limited possibility statement.",
  "uncertainty": "What any particular delegation form establishes depends on its contents; the claim does not assert that all delegation forms lack order-specific approval.",
